arguments.prompt:
You are implementing features for a Blazor Web App shipment tracker. The project has already been scaffolded at `/tmp/sv-0bf0126b52e84de7b73bbb6f9e9839ee/ShipmentTracker/` with `dotnet new blazor -int Auto -ai -au Individual`.

The project structure is:
- `ShipmentTracker/` — server project
- `ShipmentTracker.Client/` — WebAssembly client project

Key files already exist:
- `ShipmentTracker/Program.cs` — server DI and middleware (has EF Core + Identity + Auto render modes)
- `ShipmentTracker.Client/Program.cs` — client DI
- `ShipmentTracker/Data/ApplicationDbContext.cs` — EF Core context
- `ShipmentTracker/Components/App.razor` — global InteractiveAuto mode already configured
- `ShipmentTracker.Client/Pages/` — has Counter.razor, Weather.razor, Home.razor, Auth.razor, NotFound.razor

## What to implement

### 1. Shipment model in the Client project

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty; // Pending, InTransit, Delivered, Delayed
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

### 2. Service interface in the Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment> UpdateShipmentStatusAsync(int id, string newStatus);
}
```

### 3. Client-side HTTP implementation

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http) => _http = http;

    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, string newStatus)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", newStatus);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}
```

### 4. Register HttpClient and service in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to add:
```csharp
using ShipmentTracker.Client.Services;

// after AddAuthenticationStateDeserialization()
builder.Services.AddScoped(sp =>
    new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ShipmentHttpService>();
```

### 5. Server-side EF Core implementation

First, add a Shipment entity to the server's Data folder. Create `ShipmentTracker/Data/ShipmentEntity.cs`:
```csharp
namespace ShipmentTracker.Data;

using System.ComponentModel.DataAnnotations;

public class ShipmentEntity
{
    public int Id { get; set; }
    [MaxLength(50)]
    public string TrackingNumber { get; set; } = string.Empty;
    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;
    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;
    [MaxLength(50)]
    public string Status { get; set; } = string.Empty;
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    [MaxLength(200)]
    public string CustomerEmail { get; set; } = string.Empty;
    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;
}
```

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add:
```csharp
public DbSet<ShipmentEntity> Shipments => Set<ShipmentEntity>();
```
Make sure to add the proper using statement if needed.

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServerService : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServerService(ApplicationDbContext db) => _db = db;

    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await _db.Shipments.Select(e => MapToDto(e)).ToListAsync();

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await _db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : MapToDto(entity);
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, string newStatus)
    {
        var entity = await _db.Shipments.FindAsync(id) ?? throw new KeyNotFoundException($"Shipment {id} not found");
        entity.Status = newStatus;
        if (newStatus == "Delivered")
            entity.ActualDelivery = DateTime.UtcNow;
        await _db.SaveChangesAsync();
        return MapToDto(entity);
    }

    private static Shipment MapToDto(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        ActualDelivery = e.ActualDelivery,
        CustomerEmail = e.CustomerEmail,
        Description = e.Description
    };
}
```

### 6. Register server service and add API endpoints in server Program.cs

Edit `ShipmentTracker/Program.cs`. Add these using statements at the top:
```csharp
using ShipmentTracker.Client.Services;
using ShipmentTracker.Services;
```

After the `AddSingleton<IEmailSender>` line, add:
```csharp
builder.Services.AddScoped<IShipmentService, ShipmentServerService>();
```

Before `app.Run();`, add the API endpoints:
```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()));

shipments.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

shipments.MapPut("{id}/status", async (int id, string newStatus, IShipmentService service) =>
{
    try
    {
        var updated = await service.UpdateShipmentStatusAsync(id, newStatus);
        return Results.Ok(updated);
    }
    catch (KeyNotFoundException)
    {
        return Results.NotFound();
    }
});
```

### 7. Seed data

Create `ShipmentTracker/Data/SeedData.cs`:
