    private List<Shipment> _shipments = [];
    private bool _loading = true;
    private string? _error;
    private string _filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => string.IsNullOrWhiteSpace(_filterText)
        ? _shipments
        : _shipments.Where(s =>
            s.TrackingNumber.Contains(_filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Status.Contains(_filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task UpdateStatusAsync(int id, string newStatus)
    {
        try
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            var index = _shipments.FindIndex(s => s.Id == id);
            if (index >= 0) _shipments[index] = updated;
        }
        catch (Exception ex)
        {
            _error = $"Failed to update status: {ex.Message}";
        }
    }

    private static string StatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-primary",
        "Delivered" => "bg-success",
        "Delayed" => "bg-warning text-dark",
        _ => "bg-info"
    };
}
