```csharp
namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServerService : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServerService(ApplicationDbContext db) => _db = db;

    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await _db.Shipments.Select(e => MapToDto(e)).ToListAsync();

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await _db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : MapToDto(entity);
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, string newStatus)
    {
        var entity = await _db.Shipments.FindAsync(id) ?? throw new KeyNotFoundException($"Shipment {id} not found");
        entity.Status = newStatus;
        if (newStatus == "Delivered")
            entity.ActualDelivery = DateTime.UtcNow;
        await _db.SaveChangesAsync();
        return MapToDto(entity);
    }

    private static Shipment MapToDto(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        ActualDelivery = e.ActualDelivery,
        CustomerEmail = e.CustomerEmail,
        Description = e.Description
    };
}
```

