@code {
    private List<Shipment> _shipments = [];
    private bool _loading = true;
    private string? _error;
    private string _filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments => string.IsNullOrWhiteSpace(_filterText)
        ? _shipments
        : _shipments.Where(s =>
            s.TrackingNumber.Contains(_filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Status.Contains(_filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task UpdateStatusAsync(int id, string newStatus)
    {
        try
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            var index = _shipments.FindIndex(s => s.Id == id);
            if (index >= 0) _shipments[index] = updated;
        }
        catch (Exception ex)
        {
            _error = $"Failed to update status: {ex.Message}";
        }
    }

    private static string StatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-primary",
        "Delivered" => "bg-success",
        "Delayed" => "bg-warning text-dark",
        _ => "bg-info"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-1001)"
                   @bind="_trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchAsync" disabled="@_searching">
                @if (_searching)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (_notFound)
{
    <div class="alert alert-warning">
        No shipment found for tracking number <strong>@_searchedNumber</strong>. Please check and try again.
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else if (_shipment is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@_shipment.TrackingNumber</h5>
            <span class="badge @StatusBadgeClass(_shipment.Status) fs-6">@_shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@_shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@_shipment.Destination</dd>
                        <dt>Description</dt>
                        <dd>@_shipment.Description</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@_shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fw-bold text-primary">@_shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                        @if (_shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd class="text-success fw-bold">@_shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                        }
                    </dl>
                </div>
            </div>

            <!-- Status progress -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @ProgressBarClass(_shipment.Status)"
                         role="progressbar"
                         style="width: @ProgressPercent(_shipment.Status)%"
                         aria-valuenow="@ProgressPercent(_shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @_shipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string _trackingNumber = string.Empty;
    private string _searchedNumber = string.Empty;
    private Shipment? _shipment;
    private bool _searching;
    private bool _notFound;
    private string? _error;

    private async Task SearchAsync()
    {
        if (string.IsNullOrWhiteSpace(_trackingNumber)) return;

        _searching = true;
        _notFound = false;
        _error = null;
        _shipment = null;
        _searchedNumber = _trackingNumber.Trim();

        try
        {
            _shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(_searchedNumber);
            _notFound = _shipment is null;
        }
        catch (Exception ex)
        {
            _error = $"Error looking up shipment: {ex.Message}";
        }
        finally
        {
            _searching = false;
        }
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await SearchAsync();
    }

    private static string StatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "InTransit" => "bg-primary",
        "Delivered" => "bg-success",
        "Delayed" => "bg-warning text-dark",
        _ => "bg-info"
    };

    private static int ProgressPercent(string status) => status switch
    {
        "Pending" => 25,
        "InTransit" => 50,
        "Delayed" => 50,
        "Delivered" => 100,
        _ => 0
    };

    private static string ProgressBarClass(string status) => status switch
    {
        "Delayed" => "bg-warning text-dark progress-bar-striped progress-bar-animated",
        "Delivered" => "bg-success",
        _ => "progress-bar-striped progress-bar-animated"
    };
}

